import asyncio

async def bounded_call(sem: asyncio.Semaphore, coro_fn, timeout: float):
    async with sem:
        try:
            return await asyncio.wait_for(coro_fn(), timeout=timeout)
        except TimeoutError:
            return None

import threading

class SafeCounter:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._total = 0

    def add(self, n: int = 1) -> None:
        with self._lock:
            self._total += n

