from collections import deque

def bfs_distance(graph: dict[str, list[str]], start: str, goal: str) -> int:
    if start == goal:
        return 0
    q = deque([(start, 0)])
    visited = {start}
    while q:
        node, dist = q.popleft()
        for nxt in graph.get(node, []):
            if nxt == goal:
                return dist + 1
            if nxt not in visited:
                visited.add(nxt)
                q.append((nxt, dist + 1))
    return -1

